1	import java.util.List;
2	import java.util.Random;
3	import java.util.Iterator;
4	import java.util.ArrayList;
5	import java.util.HashSet;
6	
7	/**
8	 * A class representing shared characteristics of all animals within the simultion.
9	 * Animals will find food, have a gender and be able to become infected.
10	 * 
11	 * @version 2022.03.02
12	 */
13	public abstract class Animal extends Organism
14	{
15	    // A singleton shared weather object between all organisms and the simulator
16	    private static final Weather weather = Weather.getWeather();
17	    // Gender of the animal
18	    private boolean isMale;
19	    // Current health of the animal
20	    private int currentHealth;
21	    // Whether the animal is infected
22	    private boolean isInfected;
23	    
24	    /**
25	     * Create a new animal at location in field.
26	     * 
27	     * @param field The field currently occupied.
28	     * @param location The location within the field.
29	     */
30	    public Animal(boolean randomAge, Field field, Location location)
31	    {
32	        super(randomAge, field, location);
33	        
34	        if (randomAge) {
35	            currentHealth = getRand().nextInt(getMaxHealth());
36	        }
37	        if (getRand().nextInt(2) == 0) {
38	            isMale = true;
39	        }
40	        else {
41	            isMale = false;
42	        }
43	        
44	        isInfected = false;
45	    }
46	    
47	    // Abstract methods
48	    
49	    /**
50	     * Abstract method that returns the max health of the animal
51	     * 
52	     * @return the animal's max health
53	     */
54	    abstract protected int getMaxHealth();
55	    
56	    /**
57	     * Abstract method to return whether the target object is of a specific subclass of animal
58	     * 
59	     * @param target The object being compared
60	     * @return boolean True if target is of type of a specific animal subclass
61	     */
62	    abstract protected boolean getAnimalClass(Object thing);
63	    
64	    /**
65	     * Abstract method to return the list of food sources of a specific subclass of animal
66	     * 
67	     * @return ArrayList<Class> of class types that a subclass of animal is allowed to eat.
68	     */
69	    abstract protected HashSet<Class> getFoodSources();
70	    
71	    /**
72	     * Abstract method to return the list of killable classes of a specific subclass of animal
73	     * 
74	     * @return ArrayList<Class> of class types that a subclass of animal is allowed to kill.
75	     */
76	    abstract protected HashSet<Class> getKillable();
77	    // Accessor and mutator methods
78	    
79	    /**
80	     * Returns whether the animal is male
81	     * 
82	     * @boolean True if the animal is male, false if animal is female
83	     */
84	    protected boolean getGender()
85	    {
86	        return isMale;
87	    }
88	    
89	    /**
90	     * Return the current health of the animal
91	     * 
92	     * @return int of the animal's current health
93	     */
94	    protected int getCurrentHealth() {
95	        return currentHealth;
96	    }
97	    
98	    /**
99	     * Return whether the animal is infected
100	     * 
101	     * @return True if the animal is infected, false if not
102	     */
103	    protected boolean getIsInfected() {
104	        return isInfected;
105	    }
106	    
107	    /**
108	     * Sets the animal to infected state
109	     */
110	    protected void infect() {
111	        isInfected = true;
112	    }
113	    
114	    // Functional methods
115	    
116	    /**
117	     * Checks if the animal can breed
118	     * 
119	     * @return true if the animal can breed
120	     */
121	    protected boolean canBreed()
122	    {
123	        if (isMale == false)
124	        {
125	            Field field = getField();
126	            List<Location> adjacent = field.adjacentLocations(getLocation());
127	            Iterator<Location> it = adjacent.iterator();
128	            while (it.hasNext())
129	            {
130	                Location where = it.next();
131	                Object thing = field.getObjectAt(where);
132	                if (getAnimalClass(thing))
133	                {
134	                    Animal animal = (Animal) thing;
135	                    return animal.getGender() == true && getAge() >= getBreedingAge();
136	                }
137	            }
138	        }
139	        return false;
140	    }
141	    
142	    /**
143	     * A method that will make the animal object search the adjacent squares around it,
144	     * then find and eat an eligible food source.
145	     */
146	    protected Location findFood() {
147	        Field field = getField();
148	        List<Location> adjacent = field.adjacentLocations(getLocation());
149	        Iterator<Location> it = adjacent.iterator();
150	        while(it.hasNext()) {
151	            Location where = it.next();
152	            Object animal = field.getObjectAt(where);
153	            if (animal != null) {                       // makes sure to filter out empty squares
154	                Organism target = (Organism) animal;
155	                if (this.getFoodSources().contains(target.getClass()) && target.isAlive() && getRand().nextDouble() <= weather.getWeatherModifier()) {
156	                    target.setDead();
157	                    //currentHealth = this.getMaxHealth();
158	                    if (this.getFoodSources().contains(target.getClass())) {
159	                        currentHealth = this.getMaxHealth();
160	                    }
161	                }
162	            }
163	        }
164	        return null;
165	    }
166	    
167	    /**
168	     * Decrease this animal's. This could result in the animal's death by hunger.
169	     */
170	    protected void incrementHealth()
171	    {
172	        currentHealth--;
173	        if(currentHealth == 0) {
174	            setDead();
175	        }
176	    }
177	}
