7	/**
8	 * A model of a bear. Bears will eat monkeys,
9	 * but will kill monkeys and plants.
10	 * They will move and look for food and age at every step of the simulation,
11	 * and die when they reach their max age or have gone too long without food.
12	 * 
13	 * @version 2022.03.02
14	 */
15	public class Bear extends Animal implements Infectable
16	{
17	    // Characteristics shared by all bears (class variables).
18	    
19	    // The age at which a bear can start to breed.
20	    private static final int BREEDING_AGE = 15;
21	    // The age to which a bear can live.
22	    private static final int MAX_AGE = 70;
23	    // The likelihood of a bear breeding.
24	    private static final double BREEDING_PROBABILITY = 0.125;
25	    // The maximum number of births.
26	    private static final int MAX_LITTER_SIZE = 4;
27	    // The max health of a bear
28	    private static final int MAX_HEALTH = 40;
29	    // Whether the animal is diurnal or nocturnal
30	    private static final boolean IS_DIURNAL = true;
31	    
32	    // Individual characteristics (instance fields).
33	    
34	    // The food a bear will eat.
35	    private static HashSet<Class> foodSources;
36	    // The classes a bear will kill
37	    private static HashSet<Class> killable;
38	
39	    /**
40	     * Create a bear. A bear can be created as a new born (age zero
41	     * and not hungry) or with a random age and food level.
42	     * 
43	     * @param randomAge If true, the bear will have random age and hunger level.
44	     * @param field The field currently occupied.
45	     * @param location The location within the field.
46	     */
47	    public Bear(boolean randomAge, Field field, Location location)
48	    {
49	        super(randomAge, field, location);
50	        foodSources = new HashSet<>();
51	        foodSources.add(Monkey.class);
52	        
53	        killable = new HashSet<>();
54	        killable.add(Monkey.class);
55	        killable.add(Plant.class);
56	    }
57	    
58	    // Accessor and mutator methods
59	    
60	    // Accessor and mutator methods
61	    /**
62	     * Return whether the bear is diurnal
63	     * 
64	     * @return boolean True if the bea is diurnal, false if nocturnal
65	     */
66	    protected boolean getIsDiurnal() {
67	        return IS_DIURNAL;
68	    }
69	    
70	    /**
71	     * Returns breeding age of a bear
72	     * 
73	     * @return int of the bear's breeding age.
74	     */
75	    protected int getBreedingAge()
76	    {
77	        return BREEDING_AGE;
78	    }
79	    
80	    /**
81	     * Returns max age of a bear
82	     * 
83	     * @return int of the bear's max age.
84	     */
85	    protected int getMaxAge()
86	    {
87	        return MAX_AGE;
88	    }
89	    
90	    /**
91	     * Returns breeding probability of a bear
92	     * 
93	     * @return double of the bear's breeding probability
94	     */
95	    protected double getBreedingProbability()
96	    {
97	        return BREEDING_PROBABILITY;
98	    }
99	    
100	    /**
101	     * Returns max litter size of a bear
102	     * 
103	     * @return int of the bear's max litter size
104	     */
105	    protected int getMaxLitterSize()
106	    {
107	        return MAX_LITTER_SIZE;
108	    }
109	    
110	    /**
111	     * Returns whether the target animal is of instance Bear
112	     * 
113	     * @param target A target object that we want to check is of type Bear
114	     * @return boolean True if target is of type Bear
115	     */
116	    protected boolean getAnimalClass(Object target)
117	    {
118	        return target instanceof Bear;
119	    }
120	    
121	    /**
122	     * Returns the ArrayList of allowed food for a bear to eat
123	     * 
124	     * @return ArrayList<Class> of subclasses that a bear can eat
125	     */
126	    protected HashSet<Class> getFoodSources() {
127	        return foodSources;
128	    }
129	    
130	    /**
131	     * Returns the HashSet of allowed classes for a bear to kill
132	     * 
133	     * @return HashSet<Class> of subclasses that a bear can kill
134	     */
135	    protected HashSet<Class> getKillable() {
136	        return killable;
137	    }
138	    
139	    /**
140	     * Return the max health of the animal
141	     * 
142	     * @return the animal's max health
143	     */
144	    protected int getMaxHealth()
145	    {
146	        return MAX_HEALTH;
147	    }
148	    
149	    // Functional methods
150	    
151	    /**
152	     * This is what the bear does most of the time: it hunts for
153	     * monkeys. In the process, it might breed, die of hunger,
154	     * or die of old age.
155	     * @param field The field currently occupied.
156	     * @param newMonkeyes A list to return newly born bears.
157	     */
158	    public void act(List<Organism> newBears)
159	    {
160	        incrementAge();
161	        incrementHealth();
162	        if (isAlive()) {
163	            illness();
164	        }
165	        if(isAlive()) {
166	            spreadDisease();
167	            giveBirth(newBears);
168	            // Move towards a source of food if found.
169	            Location newLocation = findFood();
170	            if(newLocation == null) { 
171	                // No food found - try to move to a free location.
172	                newLocation = getField().freeAdjacentLocation(getLocation());
173	            }
174	            // See if it was possible to move.
175	            if(newLocation != null) {
176	                setLocation(newLocation);
177	            }
178	            else {
179	                // Overcrowding.
180	                setDead();
181	            }
182	        }
183	    }
184	    
185	    /**
186	     * Decides whether this animal will infect another eligible animal.
187	     */
188	    public void spreadDisease() {
189	        Field field = getField();
190	        List<Location> adjacent = field.adjacentLocations(getLocation());
191	        Iterator<Location> it = adjacent.iterator();
192	        while(it.hasNext()) {
193	            Location where = it.next();
194	            Object object = field.getObjectAt(where);
195	            if (object != null) {
196	                Organism organism = (Organism) object;
197	                if (organism instanceof Infectable && organism.isAlive() && getRand().nextDouble() <= SPREAD_PROBABILITY ) {
198	                    Animal target = (Animal) organism;
199	                    target.infect();
200	                }
201	            }
202	        }
203	    }
204	    
205	    /**
206	     * Creates and returns a new bear object
207	     * 
208	     * @return Organism object of subclass bear
209	     */
210	    protected Organism createNewOrganism(boolean randomAge, Field field, Location location)
211	    {
212	        return new Bear(randomAge, field, location);
213	    }
214	    
215	    /**
216	     * Makes the bear take extra damage if it is infected
217	     */
218	    public void illness() {
219	        if (getIsInfected()) {
220	            incrementHealth();
221	        }
222	    }
223	}
