162	            }
163	            
164	            if(newLocation != null) {
165	                setLocation(newLocation);
166	            }
167	            else {
168	                // Overcrowding.
169	                setDead();
170	            }
171	        }
172	    }
173	    
174	    /**
175	     * Creates a new Animal object for a newborn monkey
176	     * 
177	     * @return an Animal object for a newborn monkey
178	     */
179	    protected Animal createNewOrganism(boolean randomAge, Field field, Location location)
180	    {
181	        return new Monkey(randomAge, field, location);
182	    }
183	}
