4	/**
5	 * A class representing all shared characteristics of organisms.
6	 * Organisms have an age, field and a location in the field.
7	 * All organisms are able to act and breed.
8	 *
9	 * @version 2022.03.02
10	 */
11	public abstract class Organism
12	{
13	    // The organism's age
14	    private int age;
15	    // Whether the organism is alive or not.
16	    private boolean alive;
17	    // The organism's field.
18	    private Field field;
19	    // The organism's position in the field.
20	    private Location location;
21	    
22	    // A shared random number generator to control breeding.
23	    private static final Random rand = Randomizer.getRandom();
24	    
25	    /**
26	     * Constructor for objects of class Organism
27	     */
28	    public Organism(boolean randomAge, Field field, Location location)
29	    {
30	        age = 0;
31	        if (randomAge) {
32	            age = rand.nextInt(getMaxAge());
33	        }
34	        alive = true;
35	        this.field = field;
36	        setLocation(location);
37	    }
38	    
39	    // Abstract methods
40	    
41	    /**
42	     * Abstract method that returns whether the animal is diurnal or nocturnal
43	     * 
44	     * @return boolean True if the animal is diurnal, false if nocturnal
45	     */
46	    abstract protected boolean getIsDiurnal();
47	    
48	    /**
49	    * Make this organism act - that is: make it do
50	    * whatever it wants/needs to do.
51	    * @param newOrganisms A list to receive newly born organisms.
52	    */
53	    abstract public void act(List<Organism> newOrganisms);
54	    
55	    /**
56	     * Abstract method that returns the max age of the organism
57	     * 
58	     * @return the organism's max age
59	     */
60	    abstract protected int getMaxAge();
61	    
62	    /**
63	     * Abstract method that returns whether the organism can breed
64	     * 
65	     * @return boolean True if the organism can breed
66	     */
67	    abstract protected boolean canBreed();
68	    
69	    /**
70	     * Abstract method that returns the breeding age for the animal
71	     * 
72	     * @return the animal's breeding age
73	     */
74	    abstract protected int getBreedingAge();
75	    
76	    /**
77	     * Abstract methohd that returns the litter size of the animal
78	     * 
79	     * @return the animal's max litter size
80	     */
81	    abstract protected int getMaxLitterSize();
82	    
83	    /**
84	     * Abstract method that returns the breeding probability of the animal
85	     * 
86	     * @return the animal's breeding probability
87	     */
88	    abstract protected double getBreedingProbability();
89	    
90	    /**
91	     * Abstract method that returns an organism object of a specific subclass of organism
92	     * 
93	     * @return Organism object of a specified subclass
94	     */
95	    abstract protected Organism createNewOrganism(boolean randomAge, Field field, Location location);
96	    
97	    // Accessor and mutator methods
98	    
99	    /**
100	     * Return the organism's location.
101	     * @return The organism's location.
102	     */
103	    protected Location getLocation()
104	    {
105	        return location;
106	    }
107	    
108	    /**
109	     * Return the organism's field.
110	     * @return The organism's field.
111	     */
112	    protected Field getField()
113	    {
114	        return field;
115	    }
116	    
117	    /**
118	     * Returns the random object of the organism
119	     * 
120	     * @return Random object of the organism
121	     */
122	    protected Random getRand() {
123	        return rand;
124	    }
125	    
126	    /**
127	     * Returns the age of the organism
128	     * 
129	     * @return The organism's age
130	     */
131	    public int getAge()
132	    {
133	        return age;
134	    }
135	    
136	    /**
137	     * Sets the organism's age
138	     */
139	    protected void setAge(int age)
140	    {
141	        this.age = age;
142	    }
143	    
144	    /**
145	     * Check whether the organism is alive or not.
146	     * @return true if the organism is still alive.
147	     */
148	    public boolean isAlive()
149	    {
150	        return alive;
151	    }
152	    
153	    // Functional methods
154	    
155	    /**
156	     * Determines the amount of newborn a specific organism will produce
157	     * 
158	     * @return the number of newborn produced by the organism
159	     */
160	    protected int breed()
161	    {
162	        int births = 0;
163	        if(canBreed() && getRand().nextDouble() <= getBreedingProbability()) {
164	            births = getRand().nextInt(getMaxLitterSize()) + 1;
165	        }
166	        return births;
167	    }
168	    
169	    /**
170	     * Adds newborn organisms to a list
171	     */
172	    protected void giveBirth(List<Organism> newOrganisms)
173	    {
174	        // New rabbits are born into adjacent locations.
175	        // Get a list of adjacent free locations.
176	        Field field = getField();
177	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
178	        int births = breed();
179	        for(int b = 0; b < births && free.size() > 0; b++) {
180	            Location loc = free.remove(0);
181	            Organism young = createNewOrganism(false, field, loc);
182	            newOrganisms.add(young);
183	        }
184	    }
185	    
186	    /**
187	     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
188	     */
189	    protected void incrementAge()
190	    {
191	        age++;
192	        if (age > getMaxAge())
193	        {
194	            setDead();
195	        }
196	    }
197	    
198	    /**
199	     * Indicate that the organism is no longer alive.
200	     * It is removed from the field.
201	     */
202	    protected void setDead()
203	    {
204	        alive = false;
205	        if(location != null) {
206	            field.clear(location);
207	            location = null;
208	            field = null;
209	        }
210	    }
211	
212	    /**
213	     * Place the organism at the new location in the given field.
214	     * @param newLocation The organism's new location.
215	     */
216	    protected void setLocation(Location newLocation)
217	    {
218	        if(location != null) {
219	            field.clear(location);
220	        }
221	        location = newLocation;
222	        field.place(this, newLocation);
223	    }
224	}

