27	    private static final double MONKEY_CREATION_PROBABILITY = 0.08; 
28	    // The probability that a rabbit will be created in any given grid position.
29	    private static final double SLOTH_CREATION_PROBABILITY = 0.08; 
30	    // The probability that a plant will be created in any given grid position.
31	    private static final double PLANT_CREATION_PROBABILITY = 0.13;
32	    // A shared Weather object between organisms and the simulator
33	    public static final Weather weather = Weather.getWeather();
34	
35	
36	    // List of animals in the field.
